logger = logging.getLogger("desktopenv.metrics.audacity")


def _read_wav_info(file_path):
    """Read basic WAV info using the stdlib wave module. Returns dict with
    'channels', 'sample_rate', 'n_frames', 'duration', 'sampwidth'."""
    with wave.open(file_path, "rb") as wf:
        channels = wf.getnchannels()
        sample_rate = wf.getframerate()
        n_frames = wf.getnframes()
        sampwidth = wf.getsampwidth()
        duration = n_frames / sample_rate if sample_rate > 0 else 0.0
        return {
            "channels": channels,
            "sample_rate": sample_rate,
            "n_frames": n_frames,
            "duration": duration,
            "sampwidth": sampwidth,
        }


def _read_wav_samples(file_path):
    """Read WAV samples as a list of floats in [-1.0, 1.0].
    For multi-channel, returns interleaved samples."""
    with wave.open(file_path, "rb") as wf:
        n_frames = wf.getnframes()
        channels = wf.getnchannels()
        sampwidth = wf.getsampwidth()
        raw = wf.readframes(n_frames)

    total_samples = n_frames * channels
    if sampwidth == 1:
        # 8-bit unsigned
        samples = struct.unpack(f"{total_samples}B", raw)
        return [(s - 128) / 128.0 for s in samples]
    elif sampwidth == 2:
        # 16-bit signed
        samples = struct.unpack(f"<{total_samples}h", raw)
        return [s / 32768.0 for s in samples]
    elif sampwidth == 3:
        # 24-bit signed
        result = []
        for i in range(total_samples):
            b = raw[i * 3: i * 3 + 3]
            val = int.from_bytes(b, byteorder="little", signed=True)
            result.append(val / 8388608.0)
        return result
    elif sampwidth == 4:
        # 32-bit signed
        samples = struct.unpack(f"<{total_samples}i", raw)
        return [s / 2147483648.0 for s in samples]
    else:
        raise ValueError(f"Unsupported sample width: {sampwidth}")


def _rms_db(samples):
    """Compute RMS in dB for a list of float samples."""
    if not samples:
        return -100.0
    mean_sq = sum(s * s for s in samples) / len(samples)
    rms = math.sqrt(mean_sq)
    if rms < 1e-10:
        return -100.0
    return 20.0 * math.log10(rms)


def _rms_linear(samples):
    if not samples:
        return 0.0
    return math.sqrt(sum(s * s for s in samples) / len(samples))


def _pearson_corr(a, b):
    n = min(len(a), len(b))
    if n < 2:
        return 0.0
    a = a[:n]
    b = b[:n]
    mean_a = sum(a) / n
    mean_b = sum(b) / n
    num = sum((x - mean_a) * (y - mean_b) for x, y in zip(a, b))
    den_a = math.sqrt(sum((x - mean_a) ** 2 for x in a))
    den_b = math.sqrt(sum((y - mean_b) ** 2 for y in b))
    if den_a < 1e-12 or den_b < 1e-12:
        return 0.0
    return num / (den_a * den_b)


def _get_mono_samples(file_path):
    """Read WAV and return mono samples (average channels) + sample_rate."""
    info = _read_wav_info(file_path)
    samples = _read_wav_samples(file_path)
    channels = info["channels"]
    if channels > 1:
        mono = []
        for i in range(0, len(samples), channels):
            mono.append(sum(samples[i:i + channels]) / channels)
        return mono, info["sample_rate"]
    return samples, info["sample_rate"]


def _extract_time_range(samples, sr, start_time, end_time):
    """Extract samples in [start_time, end_time] seconds."""
    start_idx = int(start_time * sr)
    end_idx = int(end_time * sr)
    start_idx = max(0, min(start_idx, len(samples)))
    end_idx = max(0, min(end_idx, len(samples)))
    return samples[start_idx:end_idx]


def check_audio_duration(file_path, rule) -> float:
    """Check audio file duration.
    rule: {"expected_duration": float, "tolerance": float (default 0.5)}
    """
    try:
        if not os.path.isfile(file_path):
            logger.error(f"File not found: {file_path}")
            return 0.0
        info = _read_wav_info(file_path)
        expected = float(rule["expected_duration"])
        tolerance = float(rule.get("tolerance", 0.5))
        actual = info["duration"]
        logger.info(f"check_audio_duration: actual={actual:.2f}s, expected={expected:.2f}s, tol={tolerance:.2f}s")
        if abs(actual - expected) <= tolerance:
            return 1.0
        return 0.0
    except Exception as e:
        logger.error(f"check_audio_duration error: {e}")
        return 0.0


def check_audio_fade_in(file_path, rule) -> float:
    """Check that audio has a fade-in (RMS increases over initial windows).
    rule: {"fade_duration": float, "num_windows": int (default 5)}
    """
    try:
        if not os.path.isfile(file_path):
            return 0.0
        samples, sr = _get_mono_samples(file_path)
        fade_dur = float(rule["fade_duration"])
        num_windows = int(rule.get("num_windows", 5))

        fade_samples = int(fade_dur * sr)
        if fade_samples > len(samples):
            logger.error("Fade duration exceeds audio length")
            return 0.0

        window_size = fade_samples // num_windows
        if window_size < 1:
            return 0.0

        rms_values = []
        for i in range(num_windows):
            start = i * window_size
            end = start + window_size
            chunk = samples[start:end]
            rms_values.append(_rms_db(chunk))

        logger.info(f"check_audio_fade_in: window RMS values = {[f'{v:.1f}' for v in rms_values]}")

        # Check that RMS is generally increasing: at least (num_windows - 1) increases
        increases = sum(1 for i in range(len(rms_values) - 1) if rms_values[i + 1] > rms_values[i])
        # Allow at most 1 non-increase for robustness
        if increases >= num_windows - 2:
            return 1.0
        return 0.0
    except Exception as e:
        logger.error(f"check_audio_fade_in error: {e}")
        return 0.0


def check_audio_fade_out(file_path, rule) -> float:
    """Check that audio has a fade-out (RMS decreases over final windows).
    rule: {"fade_duration": float, "num_windows": int (default 5)}
    """
    try:
        if not os.path.isfile(file_path):
            return 0.0
        samples, sr = _get_mono_samples(file_path)
        fade_dur = float(rule["fade_duration"])
        num_windows = int(rule.get("num_windows", 5))

        fade_samples = int(fade_dur * sr)
        if fade_samples > len(samples):
            logger.error("Fade duration exceeds audio length")
            return 0.0

        window_size = fade_samples // num_windows
        if window_size < 1:
            return 0.0

        offset = len(samples) - fade_samples
        rms_values = []
        for i in range(num_windows):
            start = offset + i * window_size
            end = start + window_size
            chunk = samples[start:end]
            rms_values.append(_rms_db(chunk))

        logger.info(f"check_audio_fade_out: window RMS values = {[f'{v:.1f}' for v in rms_values]}")

        # Check that RMS is generally decreasing
        decreases = sum(1 for i in range(len(rms_values) - 1) if rms_values[i + 1] < rms_values[i])
        if decreases >= num_windows - 2:
            return 1.0
        return 0.0
    except Exception as e:
        logger.error(f"check_audio_fade_out error: {e}")
        return 0.0


def check_audio_silence_at(file_path, rule) -> float:
    """Check that a region of audio is silence (below threshold).
    rule: {"start_time": float, "end_time": float, "max_rms_db": float (default -40)}
    """
    try:
        if not os.path.isfile(file_path):
            return 0.0
        samples, sr = _get_mono_samples(file_path)
        start = float(rule["start_time"])
        end = float(rule["end_time"])
        max_rms = float(rule.get("max_rms_db", -40))

        region = _extract_time_range(samples, sr, start, end)
        if not region:
            logger.error("Empty region for silence check")
            return 0.0

        rms = _rms_db(region)
        logger.info(f"check_audio_silence_at: [{start}-{end}s] rms={rms:.2f}dB, max={max_rms}dB")
        return 1.0 if rms <= max_rms else 0.0
    except Exception as e:
        logger.error(f"check_audio_silence_at error: {e}")
        return 0.0


def check_audio_complex_edit_content(file_path, reference_path, **options) -> float:
    """Validate the complex edit against the original recording.

    Expected operation:
    - delete the original 40s-50s region
    - insert 5s of silence at 20s
    - apply fade-in to the first 3s
    - apply fade-out to the last 3s
    """
    try:
        if not os.path.isfile(file_path):
            logger.error(f"File not found: {file_path}")
            return 0.0
        if not os.path.isfile(reference_path):
            logger.error(f"Reference file not found: {reference_path}")
            return 0.0

        output, out_sr = _get_mono_samples(file_path)
        source, src_sr = _get_mono_samples(reference_path)
        if out_sr != src_sr:
            logger.info(f"Sample rate mismatch: output={out_sr}, source={src_sr}")
            return 0.0

        expected_duration = float(options.get("expected_duration", 55.0))
        duration_tolerance = float(options.get("duration_tolerance", 0.5))
        actual_duration = len(output) / out_sr if out_sr else 0.0
        if abs(actual_duration - expected_duration) > duration_tolerance:
            logger.info(
                f"Duration mismatch: actual={actual_duration:.2f}, "
                f"expected={expected_duration:.2f}, tol={duration_tolerance:.2f}"
            )
            return 0.0

        silence_start = float(options.get("silence_start", 20.0))
        silence_duration = float(options.get("silence_duration", 5.0))
        delete_start = float(options.get("delete_start", 40.0))
        delete_end = float(options.get("delete_end", 50.0))
        fade_in_duration = float(options.get("fade_in_duration", 3.0))
        fade_out_duration = float(options.get("fade_out_duration", 3.0))

        ss = int(round(silence_start * src_sr))
        sd = int(round(silence_duration * src_sr))
        ds = int(round(delete_start * src_sr))
        de = int(round(delete_end * src_sr))
        fi = int(round(fade_in_duration * src_sr))
        fo = int(round(fade_out_duration * src_sr))

        expected = source[:ds] + source[de:]
        expected = expected[:ss] + [0.0] * sd + expected[ss:]

        fade_len = min(fi, len(expected))
        for i in range(fade_len):
            expected[i] *= i / fade_len

        fade_len = min(fo, len(expected))
        fade_start = len(expected) - fade_len
        for i in range(fade_len):
            expected[fade_start + i] *= 1.0 - (i / fade_len)

        n = min(len(output), len(expected))
        if n < 1:
            return 0.0
        output = output[:n]
        expected = expected[:n]

        silence_end = silence_start + silence_duration
        silence = _extract_time_range(output, out_sr, silence_start, silence_end - 0.1)
        silence_rms = _rms_db(silence)
        max_silence_rms_db = float(options.get("max_silence_rms_db", -40.0))
        if silence_rms > max_silence_rms_db:
            logger.info(f"Inserted silence too loud: rms={silence_rms:.2f}, max={max_silence_rms_db:.2f}")
            return 0.0

        corr = _pearson_corr(output, expected)
        err = [x - y for x, y in zip(output, expected)]
        nrmse = _rms_linear(err) / max(_rms_linear(expected), 1e-12)
        min_corr = float(options.get("correlation_threshold", 0.999999))
        max_nrmse = float(options.get("max_normalized_rmse", 0.001))
        logger.info(
            f"check_audio_complex_edit_content: corr={corr:.6f}, nrmse={nrmse:.6f}, "
            f"silence_rms={silence_rms:.2f}dB"
        )
        return 1.0 if corr >= min_corr and nrmse <= max_nrmse else 0.0
    except Exception as e:
        logger.error(f"check_audio_complex_edit_content error: {e}")
        return 0.0


def check_project_file_exists(file_path, rule) -> float:
    """Check that the Audacity project was saved."""
    try:
        if os.path.isfile(file_path):
            return 1.0
        base, ext = os.path.splitext(file_path)
        alternates = []
        if ext == ".aup3":
            alternates.append(base + ".aup")
        elif ext == ".aup":
            alternates.append(base + ".aup3")
        else:
            alternates.extend([base + ".aup3", base + ".aup"])
        return 1.0 if any(os.path.isfile(path) for path in alternates) else 0.0
    except Exception as e:
        logger.error(f"check_project_file_exists error: {e}")
        return 0.0
